INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'kn'), 'A1', 'greetings', 'Greetings', 'Greet your neighbours and introduce yourself in Kannada.', 'You''ve just moved into a rented flat in Jayanagar. Lakshmamma, the house owner, comes to say hello.', '“Namaskara” works with everyone. Bengaluru is very mixed and many people switch to English or Hindi, so even “Kannada swalpa swalpa baratte” (I know a little Kannada) is warmly received.', 1, 'published', datetime('now'), datetime('now'), 1);
