INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'kn'), 'A1', 'transport', 'Transport', 'Take autos, buses and Namma Metro, and get the meter used.', 'You need to get from MG Road to Indiranagar in the evening rush.', 'Autos are meant to go by the meter, but many drivers quote a fixed price or ask for a little over it (“meter mele”). Agree before you sit in, or book through an app. Namma Metro and BMTC buses are cheap, and women who live in Karnataka travel free on BMTC''s ordinary (non-AC) buses.', 2, 'published', datetime('now'), datetime('now'), 1);
