INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'kn'), 'A1', 'food', 'Food', 'Order breakfast the Bengaluru way, at a darshini.', 'Breakfast at a busy darshini in Malleshwaram.', 'In a darshini you pay at the counter, take a token and eat standing up. “Coffee” means filter coffee. Most darshinis are vegetarian; “Naanu veg maatra tinnodu” (I only eat veg) is understood everywhere.', 3, 'published', datetime('now'), datetime('now'), 1);
