INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'kn') AND slug = 'polite-requests'), (SELECT id FROM languages WHERE code = 'en'), 'Polite requests: “kodi”, “maadi”, “heli”', 'Kannada asks politely with the “neevu” (you, polite) form of the verb, which ends in -i: “kodi” (please give), “maadi” (please do), “heli” (please say), “haaki” (please put). With friends the short form is used: “kodu”, “maadu”, “helu”.');
