INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'kn') AND slug = 'yes-no-questions'), (SELECT id FROM languages WHERE code = 'en'), 'Yes-no questions: “-aa”', 'Add -aa to a sentence to ask a yes-no question: “ide” (there is) becomes “ideya?” (is there?), “hogutte” (it goes) becomes “hogutta?” (does it go?), “aagutte” (it will do) becomes “aagutta?” (will it do?).');
