INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'kn') AND slug = 'to-a-place'), (SELECT id FROM languages WHERE code = 'en'), 'Going to a place: “-kke”, “-ige” and “-ge”', 'Kannada puts “to” at the end of the place: “-kke” after a word ending in -a (Indiranagarakke), “-ige” after one ending in -u (Bengalurige) and “-ge” after most English names (Majesticge, Nandi Hillsge).');
